#include <tcl.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
typedef struct lb_client lb_client;
typedef struct {void*context;void(*on_sign_in)(void*,const char*,const char*);double(*clock)(void*);int(*machine_binding)(void*,char*,size_t);int(*cancelled)(void*);} lb_callbacks;
extern int lb_client_create_json(const char*,const lb_callbacks*,lb_client**);
extern int lb_client_call_json(lb_client*,const char*,const char*,char**);
extern void lb_client_destroy(lb_client*);extern void lb_free(void*);
extern const char*lb_result_code(int);extern const char*lb_error_code(lb_client*);extern const char*lb_error_message(lb_client*);
extern int lb_native_binding(const char*,char*,size_t);extern int lb_derive_binding(const char*,const char*,const char*,char*,size_t);
extern int lb_verify_lease_json(const char*,const char*,const char*,double,char**);
typedef struct {lb_client*c;Tcl_Interp*i;Tcl_Obj*sign,*clock,*binding,*cancel;int failed,busy;Tcl_Command token;} Host;
static int error(Tcl_Interp*i,const char*code,const char*msg){Tcl_SetErrorCode(i,"LICENSEBOX",code,NULL);Tcl_SetObjResult(i,Tcl_NewStringObj(msg,-1));return TCL_ERROR;}
static int result(Tcl_Interp*i,int r,lb_client*c){const char*code=lb_result_code(r),*msg=code;if(c&&strcmp(code,"invalid_argument")){const char*s=lb_error_code(c);if(strcmp(s,"ok"))code=s;msg=lb_error_message(c);}return error(i,code,msg);}
static Tcl_Obj*text(const char*s){Tcl_DString d;Tcl_Encoding e=Tcl_GetEncoding(NULL,"utf-8");Tcl_ExternalToUtfDString(e,s,-1,&d);Tcl_Obj*o=Tcl_NewStringObj(Tcl_DStringValue(&d),Tcl_DStringLength(&d));Tcl_DStringFree(&d);Tcl_FreeEncoding(e);return o;}
static char*utf8(Tcl_Obj*o,Tcl_DString*d){int n;const char*s=Tcl_GetStringFromObj(o,&n);Tcl_Encoding e=Tcl_GetEncoding(NULL,"utf-8");Tcl_UtfToExternalDString(e,s,n,d);Tcl_FreeEncoding(e);if(memchr(Tcl_DStringValue(d),0,Tcl_DStringLength(d)))return NULL;return Tcl_DStringValue(d);}
static int invoke(Host*h,Tcl_Obj*prefix,int n,Tcl_Obj**args){if(!prefix)return TCL_OK;int count;Tcl_Obj**p;if(Tcl_ListObjGetElements(h->i,prefix,&count,&p)!=TCL_OK){h->failed=1;return TCL_ERROR;}Tcl_Obj**all=ckalloc(sizeof(*all)*(count+n));for(int k=0;k<count;k++)all[k]=p[k];for(int k=0;k<n;k++){all[count+k]=args[k];Tcl_IncrRefCount(args[k]);}int r=Tcl_EvalObjv(h->i,count+n,all,TCL_EVAL_GLOBAL);for(int k=0;k<n;k++)Tcl_DecrRefCount(args[k]);ckfree(all);if(r!=TCL_OK){h->failed=1;Tcl_ResetResult(h->i);}return r;}
static void sign_cb(void*p,const char*u,const char*c){Host*h=p;Tcl_Obj*a[]={text(u),text(c)};invoke(h,h->sign,2,a);}
static double clock_cb(void*p){Host*h=p;double v=0;if(invoke(h,h->clock,0,NULL)!=TCL_OK||Tcl_GetDoubleFromObj(h->i,Tcl_GetObjResult(h->i),&v)!=TCL_OK||!isfinite(v)){h->failed=1;return 0;}return v;}
static int binding_cb(void*p,char*out,size_t cap){Host*h=p;if(invoke(h,h->binding,0,NULL)!=TCL_OK)return 1;Tcl_DString d;char*s=utf8(Tcl_GetObjResult(h->i),&d);int bad=!s||(size_t)Tcl_DStringLength(&d)>=cap;if(!bad)memcpy(out,s,Tcl_DStringLength(&d)+1);else h->failed=1;Tcl_DStringFree(&d);return bad;}
static int cancel_cb(void*p){Host*h=p;int v=0;if(h->failed)return 1;if(!h->cancel)return 0;if(invoke(h,h->cancel,0,NULL)!=TCL_OK||Tcl_GetBooleanFromObj(h->i,Tcl_GetObjResult(h->i),&v)!=TCL_OK){h->failed=1;return 1;}return v;}
static void destroy(ClientData p){Host*h=p;if(h->c)lb_client_destroy(h->c);if(h->sign)Tcl_DecrRefCount(h->sign);if(h->clock)Tcl_DecrRefCount(h->clock);if(h->binding)Tcl_DecrRefCount(h->binding);if(h->cancel)Tcl_DecrRefCount(h->cancel);ckfree(h);}
static int client(ClientData p,Tcl_Interp*i,int n,Tcl_Obj*const a[]){Host*h=p;if(h->busy)return error(i,"invalid_argument","callbacks must not reenter client");if(n==2&&!strcmp(Tcl_GetString(a[1]),"close")){Tcl_DeleteCommandFromToken(i,h->token);return TCL_OK;}if(n!=4||strcmp(Tcl_GetString(a[1]),"call")){Tcl_WrongNumArgs(i,1,a,"call operation arguments-json | close");return TCL_ERROR;}Tcl_DString d;char*s=utf8(a[3],&d);if(!s){Tcl_DStringFree(&d);return error(i,"invalid_argument","NUL argument");}char*out=NULL;h->busy=1;int r=lb_client_call_json(h->c,Tcl_GetString(a[2]),s,&out);h->busy=0;Tcl_DStringFree(&d);if(h->failed){h->failed=0;lb_free(out);return error(i,"callback_error","application callback failed");}if(r){lb_free(out);return result(i,r,h->c);}if(!out)return error(i,"protocol_error","missing output");Tcl_SetObjResult(i,text(out));lb_free(out);return TCL_OK;}
static int create(ClientData p,Tcl_Interp*i,int n,Tcl_Obj*const a[]){(void)p;if(n!=3){Tcl_WrongNumArgs(i,1,a,"options-json hooks-dict");return TCL_ERROR;}Host*h=ckalloc(sizeof(*h));memset(h,0,sizeof(*h));h->i=i;const char*names[]={"on_sign_in","clock","machine_binding","cancelled"};Tcl_Obj**slots[]={&h->sign,&h->clock,&h->binding,&h->cancel};for(int k=0;k<4;k++){Tcl_Obj*key=Tcl_NewStringObj(names[k],-1);Tcl_IncrRefCount(key);int r=Tcl_DictObjGet(i,a[2],key,slots[k]);Tcl_DecrRefCount(key);if(r!=TCL_OK){destroy(h);return TCL_ERROR;}if(*slots[k])Tcl_IncrRefCount(*slots[k]);}lb_callbacks cb={h,h->sign?sign_cb:NULL,h->clock?clock_cb:NULL,h->binding?binding_cb:NULL,cancel_cb};Tcl_DString d;char*s=utf8(a[1],&d);int r=s?lb_client_create_json(s,&cb,&h->c):22;Tcl_DStringFree(&d);if(r||h->failed){int f=h->failed;destroy(h);return f?error(i,"callback_error","application callback failed"):result(i,r,NULL);}char name[128];snprintf(name,sizeof(name),"::licensebox::native::client_%p",(void*)h);h->token=Tcl_CreateObjCommand(i,name,client,h,destroy);Tcl_SetObjResult(i,Tcl_NewStringObj(name,-1));return TCL_OK;}
static int primitive(ClientData p,Tcl_Interp*i,int n,Tcl_Obj*const a[]){int kind=(int)(size_t)p,expected=kind==0?4:kind==1?2:5;if(n!=expected){Tcl_WrongNumArgs(i,1,a,kind==0?"product source raw":kind==1?"product":"token product keys-json now");return TCL_ERROR;}Tcl_DString d[3];char*s[3]={0};int count=kind==1?1:3;for(int k=0;k<count;k++){s[k]=utf8(a[k+1],&d[k]);if(!s[k]){for(int j=0;j<=k;j++)Tcl_DStringFree(&d[j]);return error(i,kind==0?"identity_unavailable":"invalid_argument","NUL argument");}}char out[128],*json=NULL;int r;if(kind==0)r=lb_derive_binding(s[0],s[1],s[2],out,sizeof(out));else if(kind==1)r=lb_native_binding(s[0],out,sizeof(out));else{double now;if(Tcl_GetDoubleFromObj(i,a[4],&now)!=TCL_OK||!isfinite(now))r=22;else r=lb_verify_lease_json(s[0],s[1],s[2],now,&json);}for(int k=0;k<count;k++)Tcl_DStringFree(&d[k]);if(r){lb_free(json);return result(i,r,NULL);}Tcl_SetObjResult(i,text(kind==2?json:out));lb_free(json);return TCL_OK;}
int Licensebox_Init(Tcl_Interp*i){if(!Tcl_InitStubs(i,"8.6",0))return TCL_ERROR;Tcl_EvalEx(i,"namespace eval ::licensebox::native {}",-1,TCL_EVAL_GLOBAL);Tcl_CreateObjCommand(i,"::licensebox::native::create",create,NULL,NULL);Tcl_CreateObjCommand(i,"::licensebox::native::derive",primitive,(ClientData)0,NULL);Tcl_CreateObjCommand(i,"::licensebox::native::binding",primitive,(ClientData)1,NULL);Tcl_CreateObjCommand(i,"::licensebox::native::verify",primitive,(ClientData)2,NULL);return Tcl_PkgProvide(i,"licensebox::native","0.2.0");}
